tl=project.GetCurrentTimeline();mp=project.GetMediaPool()
assert tl.GetName()=='v001_Director_Post_Repair_Final'
assert not (tl.GetItemListInTrack('audio',1) or [])
f=next(f for f in mp.GetRootFolder().GetSubFolderList() if f.GetName()=='03_Selected_Voice_And_Music')
lookup={c.GetClipProperty('File Path').replace('\\','/'):c for c in f.GetClipList()}
if tl.GetTrackCount('audio')<2:assert tl.AddTrack('audio','stereo')
tl.SetTrackName('audio',1,'Dialogue_Selected_63');tl.SetTrackName('audio',2,'Music_Reconformed_13')
receipt=[]
for kind,track in [('voice',1),('music',2)]:
 for v in data[kind]:
  c=lookup[v['path'].replace('\\','/')]
  item=mp.AppendToTimeline([{'mediaPoolItem':c,'recordFrame':v['record'],'mediaType':2,'trackIndex':track}])[0]
  item.SetName(v['id'])
  assert item.GetStart()==v['record']
  receipt.append({'id':v['id'],'track':track,'start':item.GetStart(),'end':item.GetEnd(),'duration':item.GetDuration(),'speed':item.GetSpeed(),'source':c.GetClipProperty('File Path')})
result={'clips':receipt,'save':resolve.GetProjectManager().SaveProject()}